import heapq

def is_valid_bst(root: list) -> bool:
    def walk(node, low, high) -> bool:
        if node is None:
            return True
        if not low < node.value < high:
            return False
        return walk(node.left, low, node.value) and walk(node.right, node.value, high)

    return walk(_build(root), float("-inf"), float("inf"))

